#include <bits/stdc++.h>
using namespace std;

int totalV, totalK, totalS;
int freqTable[100001][3];
vector<int> indexLists[3];
int cache[100001][100001][100001][3];

int findMinCost(int v, int k, int s, int last) {
    if (v == totalV && k == totalK && s == totalS) return 0;
    if (cache[v][k][s][last] != -1) return cache[v][k][s][last];
    int minVal = INT_MAX;
    if (v < totalV) {
        int pIdx = indexLists[0][v];
        int costVal = max(freqTable[pIdx][0] - v, 0)
                    + max(freqTable[pIdx][1] - k, 0)
                    + max(freqTable[pIdx][2] - s, 0) - 1;
        minVal = min(minVal, findMinCost(v + 1, k, s, 0) + costVal);
    }
    if (k < totalK && last != 0) {
        int pIdx = indexLists[1][k];
        int costVal = max(freqTable[pIdx][0] - v, 0)
                    + max(freqTable[pIdx][1] - k, 0)
                    + max(freqTable[pIdx][2] - s, 0) - 1;
        minVal = min(minVal, findMinCost(v, k + 1, s, 1) + costVal);
    }
    if (s < totalS) {
        int pIdx = indexLists[2][s];
        int costVal = max(freqTable[pIdx][0] - v, 0)
                    + max(freqTable[pIdx][1] - k, 0)
                    + max(freqTable[pIdx][2] - s, 0) - 1;
        minVal = min(minVal, findMinCost(v, k, s + 1, 2) + costVal);
    }
    return cache[v][k][s][last] = minVal;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin >> n;
    string s; cin >> s;
    vector<char> chArr(s.begin(), s.end());
    totalV = totalK = totalS = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            for (int k = 0; k <= n; k++) {
                for (int l = 0; l < 3; l++) {
                    cache[i][j][k][l] = -1;
                }
            }
        }
    }
    for (int i = 0; i < 3; i++) indexLists[i].clear();
    int posIdx = 0;
    for (char c : chArr) {
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 3; j++) {
                freqTable[i][j] = 0;
            }
        }
        if (posIdx > 0) {
            for (int j = 0; j < 3; j++) {
                freqTable[posIdx][j] = freqTable[posIdx - 1][j];
            }
        }
        if (c == 'V') {
            freqTable[posIdx][0]++;
            totalV++;
            indexLists[0].push_back(posIdx);
        } else if (c == 'K') {
            freqTable[posIdx][1]++;
            totalK++;
            indexLists[1].push_back(posIdx);
        } else {
            freqTable[posIdx][2]++;
            totalS++;
            indexLists[2].push_back(posIdx);
        }
        posIdx++;
    }
    cout << findMinCost(0, 0, 0, 2) << "\n";
    return 0;
}

